/** Operations on customers: what each one checks before it writes. */
import { problems, type Rule } from '../documents.js'
import { Customer } from '../entities/customer.js'
import { ConflictError, NotFoundError, ValidationFailedError, type FieldError } from '../errors.js'
import type { Page } from '../paging.js'
import type { UnitOfWork } from '../unit-of-work.js'

/** Properties a client may send: the database fills the others */
const FIELDS = new Set(['email', 'name', 'age', 'balance', 'visits', 'rate', 'active', 'address', 'tags', 'seen', 'ref', 'photo', 'scores', 'mixed', 'nothing', 'empty', 'deletedAt'])

/** The rules of the documents and lists inside each one */
const DOCUMENTS = {
  address: { fields: { street: { required: true }, city: { required: true }, 'zip code': {} } },
} satisfies Record<string, Rule>

/** Operations on customers. Repositories commit every write. */
export class CustomerService {
  constructor(private readonly uow: UnitOfWork) {}

  /** Checks the values against the rules of the "customers" table, and the rows they point to; throws ValidationFailedError with every problem. */
  private async validate(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Customer | null): Promise<void> {
    const creating = current === null
    const errors: FieldError[] = []
    for (const name of Object.keys(values)) if (!FIELDS.has(name)) errors.push({ field: name, message: 'is not a field of Customer' })
    if (!creating) for (const name of Object.keys(values)) if (['id', 'deletedAt'].includes(name)) errors.push({ field: name, message: 'cannot be changed' })
    {
      const value = values.email
      if (value == null) {
        if (creating || 'email' in values) errors.push({ field: 'email', message: 'is required' })
      }
    }
    {
      const value = values.name
      if (value == null) {
        if (creating || 'name' in values) errors.push({ field: 'name', message: 'is required' })
      }
    }
    {
      const value = values.rate
      if (value == null) {
        if (creating || 'rate' in values) errors.push({ field: 'rate', message: 'is required' })
      }
    }
    {
      const value = values.active
      if (value == null) {
        if (creating || 'active' in values) errors.push({ field: 'active', message: 'is required' })
      }
    }
    {
      const value = values.address
      if (value == null) {
        if (creating || 'address' in values) errors.push({ field: 'address', message: 'is required' })
      } else {
        errors.push(...problems(value, DOCUMENTS.address, 'address'))
      }
    }
    {
      const value = values.tags
      if (value == null) {
        if (creating || 'tags' in values) errors.push({ field: 'tags', message: 'is required' })
      }
    }
    if (errors.length > 0) throw new ValidationFailedError('Customer', errors)
  }

  /** Every check before a write: the values, the rows they point to, the unique values. */
  private async check(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Customer | null): Promise<void> {
    await this.validate(uow, values, current)
  }

  /** The Customer with this key; NotFoundError when there is none. */
  private async find(uow: UnitOfWork, id: string): Promise<Customer> {
    const entity = await uow.customers.findById(id)
    if (entity === null) throw new NotFoundError('Customer', id)
    return entity
  }

  /** Stores a new Customer after checking it. */
  async createCustomer(customer: Customer): Promise<Customer> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries([...FIELDS].map((field) => [field, (customer as unknown as Record<string, unknown>)[field]]))
    return this.uow.transaction(async (uow) => {
      await this.check(uow, values, null)
      const created = await uow.customers.insert(customer)
      return created
    })
  }

  /** The Customer with this key; NotFoundError when there is none. */
  async getCustomer(id: string): Promise<Customer> {
    return await this.find(this.uow, id)
  }

  /** A page of customers, by primary key. */
  async listCustomers(offset = 0, limit = 50): Promise<Page<Customer>> {
    return this.uow.customers.list(offset, limit)
  }

  /** Changes the given values of a Customer. */
  async updateCustomer(id: string, changes: Partial<Customer>): Promise<Customer> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(changes).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await this.check(uow, values, current)
      Object.assign(current, values)
      const updated = await uow.customers.update(current)
      return updated
    })
  }

  /** Marks a Customer as deleted (deletedAt); reads leave it out from then on. */
  async deleteCustomer(id: string): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if ((await uow.orders.listByCustomer(current.id)).length > 0) throw new ConflictError('Customer', 'rows of orders still point to it', ['orders'])
      current.deletedAt = new Date()
      await uow.customers.update(current)
    })
  }

  /** Adds an item to tags. */
  async addTag(id: string, tag: string): Promise<Customer> {
    return this.uow.transaction(async (uow) => {
      await this.find(uow, id)
      const updated = await uow.customers.addTag(id, tag)
      if (updated === null) throw new NotFoundError('Customer', id)
      return updated
    })
  }

  /** Removes an item from tags, by its value. */
  async removeTag(id: string, tag: string): Promise<Customer> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if (!(current.tags ?? []).includes(tag)) throw new NotFoundError('Tag', tag)
      const updated = await uow.customers.removeTag(id, tag)
      if (updated === null) throw new NotFoundError('Customer', id)
      return updated
    })
  }

  /** Adds an item to empty. */
  async addEmpty(id: string, empty: unknown): Promise<Customer> {
    return this.uow.transaction(async (uow) => {
      await this.find(uow, id)
      const updated = await uow.customers.addEmpty(id, empty)
      if (updated === null) throw new NotFoundError('Customer', id)
      return updated
    })
  }

  /** Removes an item from empty, by its position. */
  async removeEmpty(id: string, position: number): Promise<Customer> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if (!(position in (current.empty ?? []))) throw new NotFoundError('Empty', position)
      const updated = await uow.customers.removeEmpty(id, position, (current.empty ?? []).length)
      if (updated === null) throw new ConflictError('Customer', 'was changed by someone else since it was read', ['empty'])
      return updated
    })
  }
}

