/** The repositories of every table, and the transaction of each service operation. Every repository write is committed at once; `transaction()` only groups the code. */
import type { ClientSession } from 'mongoose'
import type { Db } from './database.js'
import { MemoryCustomerRepository, MongoCustomerRepository, type CustomerRepository } from './repositories/customer.js'
import { MemoryOrderRepository, MongoOrderRepository, type OrderRepository } from './repositories/order.js'

/** What services depend on: a repository per table and a transaction. */
export interface UnitOfWork {
  readonly orders: OrderRepository
  readonly customers: CustomerRepository
  /** Runs `work` with the repositories of the transaction; commits when it ends, rolls back when it throws. */
  transaction<T>(work: (uow: UnitOfWork) => Promise<T>): Promise<T>
}

/** The repositories over one database and, when there is one, the session whose transaction every query runs in. */
export class MongoUnitOfWork implements UnitOfWork {
  readonly orders: OrderRepository
  readonly customers: CustomerRepository

  constructor(
    readonly db: Db,
    readonly session: ClientSession | null = null,
  ) {
    this.orders = new MongoOrderRepository(db, session)
    this.customers = new MongoCustomerRepository(db, session)
  }

  /** Every write is stored at once: this only groups the code. */
  transaction<T>(work: (uow: UnitOfWork) => Promise<T>): Promise<T> {
    return work(this)
  }
}

/** The in-memory repositories, for tests and for trying the services without a database. */
export class MemoryUnitOfWork implements UnitOfWork {
  readonly orders = new MemoryOrderRepository()
  readonly customers = new MemoryCustomerRepository()

  /** Memory has no transactions: changes are kept as they are made. */
  transaction<T>(work: (uow: UnitOfWork) => Promise<T>): Promise<T> {
    return work(this)
  }
}

