/** Tests of the "customers" table. */
import { describe, expect, it } from 'vitest'
import { NotFoundError, ValidationFailedError } from '../src/errors.js'
import { CustomerService } from '../src/services/customer.js'
import { MemoryUnitOfWork } from '../src/unit-of-work.js'
import { useTestDatabase } from './database.js'
import { addCustomer, newCustomer } from './factories.js'

/** The repositories over the test database, opened empty for every test */
const mongoUow = useTestDatabase()

describe('customers repository', () => {
  it('is stored and read back', async () => {
    const uow = mongoUow()
    const stored = await addCustomer(uow, 1)
    const found = await uow.customers.findById(stored.id)
    expect(found).not.toBeNull()
    expect(found!.id).toEqual(stored.id)
  })

  it('lists rows by key', async () => {
    const uow = mongoUow()
    await addCustomer(uow, 1)
    await addCustomer(uow, 2)
    const page = await uow.customers.list(0, 1)
    expect(page.total).toBe(2)
    expect(page.items).toHaveLength(1)
  })

  it('stores the changes', async () => {
    const uow = mongoUow()
    const stored = await addCustomer(uow, 1)
    stored.email = 'changed'
    await uow.customers.update(stored)
    const found = await uow.customers.findById(stored.id)
    expect(found?.email).toBe('changed')
  })

  it('adds and removes one item of tags', async () => {
    const uow = mongoUow()
    const stored = await addCustomer(uow, 1)
    const before = stored.tags?.length ?? 0
    const item = ((n: number) => (`tags-${n}`))(7)
    const added = await uow.customers.addTag(stored.id, item)
    expect(added?.tags).toHaveLength(before + 1)
    expect(added?.tags?.at(-1)).toEqual(item)
    const removed = await uow.customers.removeTag(stored.id, item)
    expect(removed?.tags).toHaveLength(before)
  })

  it('adds and removes one item of empty', async () => {
    const uow = mongoUow()
    const stored = await addCustomer(uow, 1)
    const before = stored.empty?.length ?? 0
    const item = ((n: number) => ({ n }))(7)
    const added = await uow.customers.addEmpty(stored.id, item)
    expect(added?.empty).toHaveLength(before + 1)
    expect(added?.empty?.at(-1)).toMatchObject(item)
    const removed = await uow.customers.removeEmpty(stored.id, added!.empty!.length - 1, added!.empty!.length)
    expect(removed?.empty).toHaveLength(before)
    expect(await uow.customers.removeEmpty(stored.id, 0, before + 5)).toBeNull()
  })
})

describe('CustomerService', () => {
  it('creates a valid row', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new CustomerService(uow)
    const n = 100
    const created = await service.createCustomer(newCustomer(1))
    const found = await service.getCustomer(created.id)
    expect(found.id).toEqual(created.id)
  })

  it('refuses a missing value', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new CustomerService(uow)
    const n = 100
    const error: unknown = await service.createCustomer(newCustomer(1, { email: null as never })).catch((caught: unknown) => caught)
    expect(error).toBeInstanceOf(ValidationFailedError)
    expect((error as ValidationFailedError).errors.map((item) => item.field)).toEqual(['email'])
  })

  it('says when a row is missing', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new CustomerService(uow)
    await expect(service.getCustomer('ffffffffffffffffffffffff')).rejects.toBeInstanceOf(NotFoundError)
  })

  it('changes a row', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new CustomerService(uow)
    const n = 100
    const created = await service.createCustomer(newCustomer(1))
    const updated = await service.updateCustomer(created.id, { email: 'changed' })
    expect(updated.email).toBe('changed')
  })

  it('adds and removes one item of tags', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new CustomerService(uow)
    const n = 100
    const created = await service.createCustomer(newCustomer(1))
    const before = created.tags?.length ?? 0
    const item = ((n: number) => (`tags-${n}`))(7)
    const added = await service.addTag(created.id, item)
    expect(added.tags).toHaveLength(before + 1)
    const removed = await service.removeTag(created.id, item)
    expect(removed.tags).toHaveLength(before)
  })

  it('adds and removes one item of empty', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new CustomerService(uow)
    const n = 100
    const created = await service.createCustomer(newCustomer(1))
    const before = created.empty?.length ?? 0
    const item = ((n: number) => ({ n }))(7)
    const added = await service.addEmpty(created.id, item)
    expect(added.empty).toHaveLength(before + 1)
    const removed = await service.removeEmpty(created.id, added.empty!.length - 1)
    expect(removed.empty).toHaveLength(before)
    await expect(service.removeEmpty(created.id, 99)).rejects.toBeInstanceOf(NotFoundError)
  })

  it('deletes a row', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new CustomerService(uow)
    const n = 100
    const created = await service.createCustomer(newCustomer(1))
    await service.deleteCustomer(created.id)
    await expect(service.getCustomer(created.id)).rejects.toBeInstanceOf(NotFoundError)
  })
})

